using System.Net.Http.Json;
using System.Text.Json;
using ModelContextProtocol;

[McpToolType]
public class WeatherTools
{
    private readonly IHttpClientFactory _httpClientFactory;

    // Constructor injection — the MCP SDK resolves dependencies from the DI container
    public WeatherTools(IHttpClientFactory httpClientFactory)
    {
        _httpClientFactory = httpClientFactory;
    }

    [McpTool("get_weather", Description = "Get current weather for a location by latitude and longitude.")]
    public async Task<string> GetWeather(
        [McpParameter(Description = "Latitude of the location")] double latitude,
        [McpParameter(Description = "Longitude of the location")] double longitude)
    {
        var client = _httpClientFactory.CreateClient("WeatherApi");

        var url = $"v1/forecast?latitude={latitude}&longitude={longitude}&current_weather=true";
        var response = await client.GetAsync(url);
        response.EnsureSuccessStatusCode();

        var json = await response.Content.ReadFromJsonAsync<JsonElement>();
        var weather = json.GetProperty("current_weather");

        return $"Temperature: {weather.GetProperty("temperature")}°C, " +
               $"Wind: {weather.GetProperty("windspeed")} km/h, " +
               $"Condition code: {weather.GetProperty("weathercode")}";
    }

    [McpTool("get_location_name", Description = "Reverse geocode coordinates to a place name.")]
    public async Task<string> GetLocationName(
        [McpParameter(Description = "Latitude")] double latitude,
        [McpParameter(Description = "Longitude")] double longitude)
    {
        var client = _httpClientFactory.CreateClient("WeatherApi");

        var url = $"v1/forecast?latitude={latitude}&longitude={longitude}&current_weather=true&timezone=auto";
        var response = await client.GetAsync(url);
        response.EnsureSuccessStatusCode();

        var json = await response.Content.ReadFromJsonAsync<JsonElement>();
        return $"Timezone: {json.GetProperty("timezone").GetString()} " +
               $"(elevation: {json.GetProperty("elevation")}m)";
    }
}

